package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
final class ContextSignedWitnessUntilMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static ContextUniversalGroupedLocalRounds.Limits local(){return ContextSignedWitnessGroupedMatrix.local(8,WORK);}
 static ContextSignedWitnessContinuationScope.Receipt stable(boolean reverse,boolean trusted)throws Exception{Snapshot x=ContextSignedWitnessReceiverMatrix.bind(true,"!anchor(1);"),a=ContextSignedWitnessReceiverMatrix.bind(false,"!$u p(u)&&~q(u);"),b=ContextSignedWitnessReceiverMatrix.bind(false,"!b(1);");List<Snapshot> fs=reverse?Arrays.asList(b,a):Arrays.asList(a,b);if(trusted)fs=Collections.singletonList(ContextProductionNativeBinding.trusted("until",fs,WORK));return ContextSignedWitnessStopMatrix.root(x,fs);}
 static ContextSignedWitnessUntilStop.Result yes(ContextSignedWitnessContinuationScope.Receipt start,ContextUniversalGroupedLocalRounds.Limits local,int max){ContextSignedWitnessUntilStop.Result r=ContextSignedWitnessUntilStop.run(start,64,start.limits,local,max,WORK,64);require(r.status==ContextSignedWitnessUntilStop.Status.QUIESCENT,r.phase+": "+r.reason);require(r.stopping!=null&&r.terminal==r.stopping.terminal&&r.terminal.scope==r.output,"actual final stopping certificate, no historical substitution");return r;}
 static void positive()throws Exception{for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessContinuationScope.Receipt s=stable(reverse,false);ContextUniversalGroupedLocalRounds.Limits l=local();ContextSignedWitnessUntilStop.Result r=yes(s,l,3);require(r.history.size()==1&&!r.history.get(0).result.history.get(0).changes.any()&&r.output.generation==2,"first verified unchanged transition stops early, not at requested maximum");require(r.terminal.checks.size()==3&&r.terminal.certificates.size()==3,"ALL final independent cuts certified");require(r.start==s&&r.local==l&&r.maximumRounds==3,"exact termination request bound");}System.out.println("SIGNED_WITNESS_UNTIL orders=2 earlyQualifiedStop=true actualFinalScope=true allFinalCuts=true suppliedProfileOnly=true");}
 static void progress()throws Exception{ContextSignedWitnessSecondMatrix.Fixture f=new ContextSignedWitnessSecondMatrix.Fixture(false,false);ContextUniversalGroupedLocalRounds.Limits l=local();ContextSignedWitnessUntilStop.Result r=yes(f.scope,l,2);require(r.history.size()==2&&r.history.get(0).result.history.get(0).changes.any()&&!r.history.get(1).result.history.get(0).changes.any(),"real production requires later unchanged pass before final qualification");require(r.output.generation==3&&r.output.current().packet.items.stream().anyMatch(i->i.atom.predicate.equals("end")&&!i.atom.positive&&i.proofs.stream().anyMatch(p->p.sources.size()==5)),"five-source negative end retained through qualified stop");if(Boolean.getBoolean("kanger.until.fullAudit")){ContextSignedWitnessUntilStop.Receipt full=ContextSignedWitnessUntilStop.inspect(r,f.scope,64,f.scope.limits,l,2,WORK,64);require(full.result==r,"full fresh TWO-transition termination audit");}System.out.println("SIGNED_WITNESS_UNTIL_PROGRESS realProductionThenQualifiedStop=true limitNotEquilibrium=true exactFiveSourceProof=true");}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessUntilStop.Result r,String why){require(r.status==ContextSignedWitnessUntilStop.Status.INCOMPLETE&&r.start==null&&r.output==null&&r.local==null&&r.history.isEmpty()&&r.terminal==null&&r.stopping==null,why+": no partial termination prefix");}
 static void boundaries()throws Exception{
  ContextSignedWitnessContinuationScope.Receipt s=stable(false,true);ContextUniversalGroupedLocalRounds.Limits l=local();incomplete(ContextSignedWitnessUntilStop.run(s,64,s.limits,l,0,WORK,64),"zero maximum");incomplete(ContextSignedWitnessUntilStop.run(s,64,s.limits,l,64,WORK,64),"generation cap");incomplete(ContextSignedWitnessUntilStop.run(s,63,s.limits,l,1,WORK,64),"exact rows");incomplete(ContextSignedWitnessUntilStop.run(s,64,s.limits,l,1,1,64),"fresh audit bound");incomplete(ContextSignedWitnessUntilStop.run(s,64,s.limits,l,1,WORK,0),"validation capacity");
  Snapshot x=ContextSignedWitnessReceiverMatrix.bind(true,"!anchor(1); !@x left(x)&&right(x)->p(x);"),a=ContextSignedWitnessReceiverMatrix.bind(false,"!p(1); !left(1); !$u aa(u)&&~aside(u);"),b=ContextSignedWitnessReceiverMatrix.bind(false,"!~p(1); !right(1); !$u bb(u)&&~bside(u);");ContextSignedWitnessContinuationScope.Receipt clash=ContextSignedWitnessStopMatrix.root(x,Arrays.asList(a,b));ContextSignedWitnessUntilStop.Result r=ContextSignedWitnessUntilStop.run(clash,64,clash.limits,l,2,WORK,64);require(r.status==ContextSignedWitnessUntilStop.Status.REFUTED&&r.output==null&&r.stopping==null&&r.history.size()==1,"complete real conflict stops before any output barrier/stopping receipt");require(r.terminal==r.history.get(0).result.refutation&&r.terminal.checks.size()==3&&r.terminal.checks.values().stream().flatMap(c->c.emptyProofs.stream()).anyMatch(p->p.support.sources.size()==4),"actual all-cut owned four-Source rejection");ContextSignedWitnessUntilStop.inspect(r,clash,64,clash.limits,l,2,WORK,1);require(true,"direct refutation termination audit at capacity1");ContextSignedWitnessSecondMatrix.Fixture f=new ContextSignedWitnessSecondMatrix.Fixture(false,false);ContextSignedWitnessUntilStop.Result bounded=ContextSignedWitnessUntilStop.run(f.scope,64,f.scope.limits,l,1,WORK,64);incomplete(bounded,"actual production with one allowed transition");require(bounded.phase.equals("round-limit"),"progress at bound is INCOMPLETE, never stop or conflict");System.out.println("SIGNED_WITNESS_UNTIL_BOUNDARIES requestBoundsNoPrefixes=true actualAllCutRefutation=true limitNotConflict=true noAdmission=true");
 }
 static void integrity()throws Exception{
  ContextSignedWitnessContinuationScope.Receipt s=stable(false,true);ContextUniversalGroupedLocalRounds.Limits l=local();ContextSignedWitnessUntilStop.Result r=yes(s,l,2);ContextSignedWitnessUntilStop.Receipt receipt=ContextSignedWitnessUntilStop.inspect(r,s,64,s.limits,l,2,WORK,64);
  reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,1,WORK,64),"exact requested maximum");reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,local(),2,WORK,64),"local request identity");reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,1,64),"fresh audit budget");
  Object saved=ContextSignedWitnessBarrierMatrix.replace(r,"history",Collections.emptyList());reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,WORK,64),"lost actual transition history");ContextSignedWitnessBarrierMatrix.replace(r,"history",saved);saved=ContextSignedWitnessBarrierMatrix.replace(r,"stopping",null);reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,WORK,64),"no stopping certificate means no quiescence");ContextSignedWitnessBarrierMatrix.replace(r,"stopping",saved);saved=ContextSignedWitnessBarrierMatrix.replace(r,"output",s);reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,WORK,64),"cannot rewind output generation");ContextSignedWitnessBarrierMatrix.replace(r,"output",saved);saved=ContextSignedWitnessBarrierMatrix.replace(r,"terminal",r.history.get(0).result.history.get(0).checks);reject(()->ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,WORK,64),"historical local checks not final scope");ContextSignedWitnessBarrierMatrix.replace(r,"terminal",saved);ContextSignedWitnessUntilStop.check(receipt,s,64,s.limits,l,2,WORK,1);require(true,"restored exact termination ledger freshly audited");
  ContextSignedWitnessAuditSession session=ContextSignedWitnessAuditSession.open(WORK,1);try{ContextSignedWitnessContinuationScope.check(s,WORK,64);long hits=session.hits;ContextSignedWitnessContinuationScope.check(s,WORK,64);require(session.hits>hits&&session.entries()==1,"completed same-request lineage audit reused only inside owned bounded invocation");}finally{session.close();}require(session.entries()==0,"invocation audit entries cleared on close");reject(()->ContextSignedWitnessContinuationScope.check(s,1,64),"closed invocation cannot lend historical authority to fresh small budget");
  try(ContextSignedWitnessAuditSession failed=ContextSignedWitnessAuditSession.open(WORK,64)){ContextSignedWitnessContinuationScope.check(s,WORK,64);reject(()->ContextSignedWitnessContinuationScope.check(s,1,64),"different smaller audit request cannot reuse completed larger-budget entry");reject(()->ContextSignedWitnessContinuationScope.check(s,WORK,64),"failed invocation is poisoned, no success from old memo");}try(ContextSignedWitnessAuditSession fresh=ContextSignedWitnessAuditSession.open(WORK,64)){ContextSignedWitnessContinuationScope.check(s,WORK,64);require(fresh.verified>0,"new invocation fully verifies again after prior failure");}
  System.out.println("SIGNED_WITNESS_UNTIL_INTEGRITY modeRequestBudgetHistoryFinalScopeAndStopReceiptExact=true noAdmission=true");
 }
}
